// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;

import org.junit.jupiter.api.Test;

class PlanLifecycleStoreTest {

	private static final LogicalLearningKey LOGICAL = LogicalLearningKey.of(
			"difference", "expression", "children", "predicates", "x", "none",
			"bag|duplicate-sensitive|sparql-unbound", "default");
	private static final LearningApplicability APPLICABILITY = new LearningApplicability(
			1L, 2L, "unconditional", 3L, 4L, 5L);
	private static final PhysicalResidualKey MATERIALIZED = physical("materialized-hash");
	private static final PhysicalResidualKey STREAMING = physical("streaming-correlated");

	@Test
	void d4_01ValidCatastrophicExecutionIsQuarantinedImmediately() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope planned = envelope(90.0d, 100.0d, 110.0d);

		assertTrue(store.observe(LOGICAL, STREAMING, APPLICABILITY, planned, 1_000.0d,
				true, 120.0d, 1L));

		PlanLifecycleStore.Decision decision = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, planned, true);
		assertEquals(PlanLifecycleStore.State.QUARANTINED, decision.state());
		assertFalse(decision.eligible());
		assertEquals(Double.MAX_VALUE, decision.comparisonCost());
	}

	@Test
	void d4_02InvalidExecutionCannotChangeLifecycle() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		long revision = store.revision();

		assertFalse(store.observe(LOGICAL, STREAMING, APPLICABILITY, envelope(90.0d, 100.0d, 110.0d),
				1_000.0d, false, 120.0d, 1L));
		assertEquals(revision, store.revision());
		assertEquals(PlanLifecycleStore.State.MONITORING,
				store.decision(LOGICAL, STREAMING, APPLICABILITY, envelope(90.0d, 100.0d, 110.0d), true)
						.state());
	}

	@Test
	void d4_03OverlappingChallengerRetainsLastGood() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope incumbent = envelope(90.0d, 100.0d, 110.0d);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);

		PlanLifecycleStore.Decision challenger = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, envelope(80.0d, 95.0d, 105.0d), true);

		assertFalse(challenger.eligible());
		assertEquals(MATERIALIZED.digest(), challenger.lastGoodPhysicalDigest());
		assertEquals("credible-interval-overlap-retain-last-good", challenger.reason());
	}

	@Test
	void d4_04DecisiveChallengerSwitchesOnlyAfterVerification() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, envelope(90.0d, 100.0d, 110.0d), 100.0d,
				true, Double.POSITIVE_INFINITY, 1L);
		PlanLifecycleStore.ObjectiveEnvelope challengerEnvelope = envelope(60.0d, 70.0d, 80.0d);

		PlanLifecycleStore.Decision beforeVerification = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, challengerEnvelope, true);
		assertTrue(beforeVerification.eligible());
		assertFalse(beforeVerification.lastGood());
		assertEquals(PlanLifecycleStore.State.APPLYING, beforeVerification.state());
		assertEquals(MATERIALIZED.digest(), beforeVerification.lastGoodPhysicalDigest());

		store.observe(LOGICAL, STREAMING, APPLICABILITY, challengerEnvelope, 70.0d, true, 110.0d, 2L);
		assertTrue(store.decision(LOGICAL, STREAMING, APPLICABILITY, challengerEnvelope, true).lastGood());
		assertFalse(store.decision(LOGICAL, MATERIALIZED, APPLICABILITY,
				envelope(90.0d, 100.0d, 110.0d), true).lastGood());
	}

	@Test
	void d4_05CatastrophicChallengerRollsBackOnNextDecisionAndPersists() throws Exception {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope incumbent = envelope(90.0d, 100.0d, 110.0d);
		PlanLifecycleStore.ObjectiveEnvelope challenger = envelope(50.0d, 60.0d, 70.0d);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);
		assertTrue(store.decision(LOGICAL, STREAMING, APPLICABILITY, challenger, true).eligible());

		store.observe(LOGICAL, STREAMING, APPLICABILITY, challenger, 10_000.0d, true, 110.0d, 2L);
		assertFalse(store.decision(LOGICAL, STREAMING, APPLICABILITY, challenger, true).eligible());
		assertTrue(store.decision(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, true).lastGood());

		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			store.writeTo(output);
		}
		PlanLifecycleStore restored;
		try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = PlanLifecycleStore.readFrom(input, 16);
		}
		assertEquals(PlanLifecycleStore.State.QUARANTINED,
				restored.decision(LOGICAL, STREAMING, APPLICABILITY, challenger, true).state());
		assertTrue(restored.decision(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, true).lastGood());
	}

	@Test
	void monitoringProfileExposesOnlyMonitoringWithoutDiscardingPersistedSafetyState() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope planned = envelope(90.0d, 100.0d, 110.0d);
		store.observe(LOGICAL, STREAMING, APPLICABILITY, planned, 1_000.0d, true, 120.0d, 1L);

		PlanLifecycleStore.Decision monitoring = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, planned, false);
		assertEquals(PlanLifecycleStore.State.MONITORING, monitoring.state());
		assertTrue(monitoring.eligible());
		assertEquals(planned.point(), monitoring.comparisonCost());

		PlanLifecycleStore.Decision enforced = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, planned, true);
		assertEquals(PlanLifecycleStore.State.QUARANTINED, enforced.state(),
				"Promoting the rollout must enforce the safety state collected during Monitoring");
		assertFalse(enforced.eligible());
	}

	@Test
	void periodTwoSelectionFreezesLastGoodAndBlocksChallenger() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope firstA = envelope(90.0d, 100.0d, 110.0d);
		PlanLifecycleStore.ObjectiveEnvelope firstB = envelope(60.0d, 70.0d, 80.0d);
		PlanLifecycleStore.ObjectiveEnvelope secondA = envelope(25.0d, 30.0d, 35.0d);
		PlanLifecycleStore.ObjectiveEnvelope secondB = envelope(15.0d, 20.0d, 24.0d);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, firstA, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);
		store.decision(LOGICAL, STREAMING, APPLICABILITY, firstB, true);
		store.observe(LOGICAL, STREAMING, APPLICABILITY, firstB, 70.0d, true, 110.0d, 2L);
		store.decision(LOGICAL, MATERIALIZED, APPLICABILITY, secondA, true);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, secondA, 30.0d, true, 80.0d, 3L);
		store.decision(LOGICAL, STREAMING, APPLICABILITY, secondB, true);

		store.observe(LOGICAL, STREAMING, APPLICABILITY, secondB, 20.0d, true, 35.0d, 4L);

		PlanLifecycleStore.Decision blocked = store.decision(
				LOGICAL, STREAMING, APPLICABILITY, secondB, true);
		assertEquals(PlanLifecycleStore.State.BLOCKED, blocked.state());
		assertEquals("period-two-freeze-last-good", blocked.reason());
		assertTrue(store.decision(LOGICAL, MATERIALIZED, APPLICABILITY, secondA, true).lastGood());
	}

	@Test
	void epochChangeReturnsProtectedStateToMonitoring() {
		PlanLifecycleStore store = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope incumbent = envelope(90.0d, 100.0d, 110.0d);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);
		assertTrue(store.decision(LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, true).lastGood());

		store.markAllStale();

		PlanLifecycleStore.Decision decision = store.decision(
				LOGICAL, MATERIALIZED, APPLICABILITY, incumbent, true);
		assertEquals(PlanLifecycleStore.State.MONITORING, decision.state());
		assertFalse(decision.lastGood());
		assertEquals("no-last-good-robust-upper", decision.reason());
	}

	@Test
	void protectedLastGoodAndQuarantineAreNeverEvictedForMonitoringData() {
		PlanLifecycleStore store = new PlanLifecycleStore(2);
		PlanLifecycleStore.ObjectiveEnvelope envelope = envelope(90.0d, 100.0d, 110.0d);
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, envelope, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);
		store.observe(LOGICAL, STREAMING, APPLICABILITY, envelope, 1_000.0d, true, 120.0d, 2L);
		PhysicalResidualKey ordinary = physical("memoized-correlated");

		PlanLifecycleStore.Decision rejectedAdmission = store.decision(
				LOGICAL, ordinary, APPLICABILITY, envelope, true);

		assertEquals(2, store.size());
		assertEquals("monitoring-capacity-protected", rejectedAdmission.reason());
		assertTrue(store.decision(LOGICAL, MATERIALIZED, APPLICABILITY, envelope, true).lastGood());
		assertEquals(PlanLifecycleStore.State.QUARANTINED,
				store.decision(LOGICAL, STREAMING, APPLICABILITY, envelope, true).state());
	}

	private static PlanLifecycleStore.ObjectiveEnvelope envelope(double lower, double point, double upper) {
		return new PlanLifecycleStore.ObjectiveEnvelope(lower, point, upper);
	}

	private static PhysicalResidualKey physical(String algorithm) {
		return PhysicalResidualKey.of(algorithm, "statement-pattern", "spoc", "per-binding", "none", "none",
				"none", "bound");
	}
}
